// NR addon restarts with HA so globals clear on each boot.
// First connection = boot. Subsequent reconnects are skipped.
const fired = global.get('bootAnnounceDone') || false;
if (fired) { return null; }
global.set('bootAnnounceDone', true);
return msg;

flow.set('ups_down', true);
msg.payload = {
    title: '⚠️ UPS monitoring lost',
    message: 'sensor.myups_status has been unavailable for 10+ minutes. Check the Network UPS Tools addon (Settings > Add-ons).'
};
return msg;

if (flow.get('ups_down')) {
    flow.set('ups_down', false);
    msg.payload = {
        title: '✅ UPS monitoring restored',
        message: 'sensor.myups_status is back: ' + msg.payload
    };
    return msg;
}
return null;

const pveRaw    = flow.get('pve_temp');
const odroidRaw = flow.get('odroid_temp');
const opiRaw    = flow.get('opi_temp');

if (pveRaw === null && odroidRaw === null && opiRaw === null) {
    node.status({fill:'red', shape:'ring', text:'No temp data - waiting for sensors'});
    return null;
}

const pveTemp    = parseFloat(pveRaw)    || 0;
const odroidTemp = parseFloat(odroidRaw) || 0;
const opiTemp    = parseFloat(opiRaw)    || 0;

const maxTemp = Math.max(pveTemp, odroidTemp, opiTemp);
let acState = flow.get('ac_state') || 'off';

node.status({fill:'blue', shape:'dot', text: 'PVE:' + pveTemp + ' OD:' + odroidTemp + ' OPI:' + opiTemp + ' Max:' + maxTemp.toFixed(1) + 'C [' + acState + ']'});

let action = null;

if (acState === 'off') {
    if (maxTemp >= 40) { flow.set('ac_state', 'low'); action = 'turn_on_low'; }
} else if (acState === 'low') {
    if (maxTemp >= 45) { flow.set('ac_state', 'high'); action = 'fan_high'; }
    else if (maxTemp < 35) { flow.set('ac_state', 'off'); action = 'turn_off'; }
} else if (acState === 'high') {
    if (maxTemp < 35) { flow.set('ac_state', 'off'); action = 'turn_off'; }
    else if (maxTemp < 45) { flow.set('ac_state', 'low'); action = 'fan_low'; }
}

if (!action) return null;

msg.cmd = action;
msg.maxTemp = maxTemp;
return msg;

try {
    const body = JSON.parse(msg.payload);
    msg.payload = (body.choices?.[0]?.message?.content || '')
        .trim()
        .replace(/#/g, '')
        .replace(/['\u2018\u2019]s([a-z])/gi, 's $1')
        .replace(/['\u2018\u2019]/g, '')
        .replace(/\s+/g, ' ')
        .trim();
    if (!msg.payload) {
        msg.payload = 'Irrigation summary unavailable.';
    }
} catch (e) {
    msg.payload = 'Irrigation summary unavailable (parse error).';
}
return msg;

const soilRaw = msg.soil;
const soil = (soilRaw !== null && soilRaw !== undefined &&
              !['unavailable', 'unknown'].includes(String(soilRaw).toLowerCase()))
    ? soilRaw : null;

const precipToday = msg.precip_today  ?? 0;
const precipTmrw  = msg.precip_tomorrow ?? 0;
const rainToday   = msg.rain_today    ?? 0;
const lawnTime    = msg.lawn_time     ?? 0;
const tempHigh    = msg.temp_high     ?? 'unknown';

const rained    = parseFloat(rainToday) > 0;
const scheduled = parseFloat(lawnTime) > 0;

let irrigationLine;
if (soil === null) {
    irrigationLine = 'Soil moisture sensor is temporarily unavailable. The automated system will reassess when it recovers.';
} else if (rained) {
    irrigationLine = 'Irrigation was skipped because ' + rainToday + 'mm of rain fell today.';
} else if (scheduled) {
    irrigationLine = 'Irrigation ran today. The lawn was scheduled for ' + lawnTime + ' minutes.';
} else {
    irrigationLine = 'No watering was needed today. Soil moisture is already at ' + soil + '%, above the irrigation threshold.';
}

const soilLine = soil !== null ? soil + '%' : 'temporarily unavailable';

const prompt =
    'You are a friendly home automation assistant for a garden in Canberra, Australia. ' +
    'The irrigation system is FULLY AUTOMATED. It uses weather sensors and evapotranspiration ' +
    'calculations to decide when to run, and operates up to 4 times per day without any human input. ' +
    'The homeowner does not need to take action. ' +
    'Write exactly two short sentences: one explaining the irrigation outcome for today and why, ' +
    'one brief comment on the outlook for tomorrow. ' +
    'Output clean prose only. Never use the # character. ' +
    'Always confirm that no action is required from the reader. ' +
    'Be specific with the numbers. No preamble.\n\n' +
    'Data for today:\n' +
    '- Soil moisture: ' + soilLine + '\n' +
    '- High temperature today: ' + tempHigh + ' degrees C\n' +
    '- Rain today: ' + rainToday + 'mm\n' +
    '- Rain chance today: ' + precipToday + '%\n' +
    '- Rain chance tomorrow: ' + precipTmrw + '%\n' +
    '- Lawn watering scheduled: ' + lawnTime + ' min\n' +
    '- ' + irrigationLine;

msg.payload = JSON.stringify({
    model: 'gemma2:2b',
    messages: [{ role: 'user', content: prompt }],
    stream: false
});
msg.headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer sk-homelab-master'    
};
msg.requestTimeout = 180000;
return msg;

